contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public {
        require(amount > 0 && amount <= 10**24);
        c.NETM(); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(amount <= balBefore);
        c.burn(amount); if (__ESBMC_reverted()) return;
        assert(c.totalSupply() + amount == supplyBefore && c.balanceOf(address(this)) + amount == balBefore);
    }
    receive() external payable {}
}

